-- Additive OSRM demo routes with a real city fork.
-- Plan: Huzhou -> Anji -> Hangzhou; alternative: Huzhou -> Deqing -> Hangzhou.
-- Geometry is copied from OSRM GeoJSON step polylines in WGS84; both routes remain PENDING_VERIFICATION.
-- The alternative is shorter and faster, and the fork is large enough for RoadMatcher to distinguish at 1.5 km sampling / 0.15 km threshold.
USE logistics_system;
SET NAMES utf8mb4;
SET @admin_id := (SELECT id FROM users WHERE username='admin' AND account_status='APPROVED' LIMIT 1);
INSERT INTO routes (route_name,origin_city,destination_city,route_status,data_source,map_request_json,map_response_reference,version_number,created_by)
SELECT '新增演示计划路线：湖州—安吉—杭州 OSRM','湖州','杭州','PENDING_VERIFICATION','OSRM_OSM_DRIVING_V5',CAST('{"origin":"120.063940,30.810775","destination":"120.115022,30.380229","via":"119.680000,30.640000","viaCity":"安吉","overview":"full","steps":"true","coordinateSystem":"WGS84","geometries":"geojson","alternatives":"false","continue_straight":"false","profile":"driving"}' AS JSON),'backend/target/osrm-demo-anji.json#routes[0]',1,@admin_id
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM routes WHERE route_name='新增演示计划路线：湖州—安吉—杭州 OSRM');
SET @plan_route_id := (SELECT id FROM routes WHERE route_name='新增演示计划路线：湖州—安吉—杭州 OSRM' LIMIT 1);
INSERT INTO route_segments (route_id,sequence_number,from_city,to_city,road_name,road_type,distance_km,estimated_minutes,geometry_json,map_source,map_request_json,map_response_reference,truck_access_status)
